/**
 * components/shared/pdf/Form1065.js - Form 1065 React-PDF document.
 *
 * Fileable-quality summary of the LLC partnership return. Page 1 = income +
 * deductions + ordinary business income (line 22). Page 2 = Schedule B summary,
 * Schedule K, Schedule L (beginning/ending balance sheet), Schedule M-1, M-2.
 *
 * Used by: TaxCenter (Financials > Tax Center).
 *
 * @perf lazy-load only (heavy @react-pdf/renderer); never import at top level.
 * @see docs/MONEY.md (tax)
 */
import React from 'react';
import { Document, Page, Text, View, StyleSheet } from '@react-pdf/renderer';
import { formatTaxAmount } from '../../../utils/ledger-tax';
import { PRINT } from '../../../utils/printPalette';

const P = { ...PRINT, light: PRINT.lightRule };

const s = StyleSheet.create({
  page:       { padding: 36, fontFamily: 'Helvetica', fontSize: 9, color: P.nearBlack, backgroundColor: P.warmWhite },
  title:      { fontSize: 16, fontWeight: 700, marginBottom: 2 },
  subtitle:   { fontSize: 10, color: P.muted, marginBottom: 14 },
  section:    { marginTop: 14, fontSize: 11, color: P.orange, textTransform: 'uppercase', letterSpacing: 1, paddingBottom: 3, borderBottomWidth: 0.5, borderBottomColor: P.rule, borderBottomStyle: 'solid' },
  row:        { flexDirection: 'row', paddingVertical: 3 },
  rowDim:     { flexDirection: 'row', paddingVertical: 3, color: P.muted, fontStyle: 'italic' },
  cellLine:   { width: 38 },
  cellLabel:  { flex: 1 },
  cellAmt:    { width: 110, textAlign: 'right', fontVariantNumeric: 'tabular-nums' },
  total:      { flexDirection: 'row', paddingVertical: 5, borderTopWidth: 0.5, borderTopColor: P.nearBlack, borderTopStyle: 'solid', fontWeight: 700 },
  bsRow:      { flexDirection: 'row', paddingVertical: 2 },
  bsLabel:    { flex: 1 },
  bsBegin:    { width: 95, textAlign: 'right' },
  bsEnd:      { width: 95, textAlign: 'right' },
  bsHdr:      { flexDirection: 'row', paddingVertical: 4, borderBottomWidth: 0.5, borderBottomColor: P.nearBlack, borderBottomStyle: 'solid', fontWeight: 700 },
  m2hdr:      { flexDirection: 'row', paddingVertical: 4, borderBottomWidth: 0.5, borderBottomColor: P.nearBlack, borderBottomStyle: 'solid', fontWeight: 700 },
  m2col:      { flex: 1, paddingHorizontal: 4 },
  m2colName:  { width: 110, paddingHorizontal: 4 },
  m2colNum:   { width: 78, textAlign: 'right', paddingHorizontal: 4 },
  footer:     { position: 'absolute', bottom: 18, left: 36, right: 36, textAlign: 'center', fontSize: 8, color: P.muted, letterSpacing: 1 },
  tag:        { fontSize: 8, color: P.muted, marginTop: 2 },
});

const F = (n) => formatTaxAmount(n);

/**
 * Signed amount, for the Schedule M-1 reconciling items only.
 * @gotcha formatTaxAmount drops the sign, which is right for IRS form boxes but
 *         wrong here: a fall in receivables is a NEGATIVE reconciling item, and
 *         printing it unsigned makes M-1 look like it does not add up.
 */
const FS = (n) => {
  const v = Number(n) || 0;
  return `${v < 0 ? '-' : ''}${formatTaxAmount(v)}`;
};

function LineRow({ line, label, amount, dim }) {
  return (
    <View style={dim ? s.rowDim : s.row}>
      <Text style={s.cellLine}>{line}</Text>
      <Text style={s.cellLabel}>{label}</Text>
      <Text style={s.cellAmt}>{F(amount)}</Text>
    </View>
  );
}

/** A Schedule L balance-sheet block: union of beginning/ending accounts, sorted by code, with a total row. */
function BSSection({ title, beginning, ending }) {
  const allKeys = new Map();
  (beginning || []).forEach((r) => allKeys.set(r.account.id, r.account));
  (ending    || []).forEach((r) => allKeys.set(r.account.id, r.account));
  const beginById = new Map((beginning || []).map((r) => [r.account.id, r.balance]));
  const endById   = new Map((ending    || []).map((r) => [r.account.id, r.balance]));
  const rows = [...allKeys.values()].sort((a, b) =>
    String(a.code || '').localeCompare(String(b.code || ''))
  );
  const sum = (m) => [...m.values()].reduce((a, b) => a + b, 0);
  return (
    <View>
      <Text style={s.section}>{title}</Text>
      <View style={s.bsHdr}>
        <Text style={s.bsLabel}>Account</Text>
        <Text style={s.bsBegin}>Beginning</Text>
        <Text style={s.bsEnd}>Ending</Text>
      </View>
      {rows.map((a) => (
        <View key={a.id} style={s.bsRow}>
          <Text style={s.bsLabel}>{a.code}  {a.name}</Text>
          <Text style={s.bsBegin}>{F(beginById.get(a.id) || 0)}</Text>
          <Text style={s.bsEnd}>{F(endById.get(a.id)   || 0)}</Text>
        </View>
      ))}
      <View style={[s.total, { paddingTop: 4 }]}>
        <Text style={s.bsLabel}>Total</Text>
        <Text style={s.bsBegin}>{F(sum(beginById))}</Text>
        <Text style={s.bsEnd}>{F(sum(endById))}</Text>
      </View>
    </View>
  );
}

/**
 * The two-page Form 1065 document.
 * @param {object} props
 * @param {object} props.form1065 - builder output (page1, schedK, schedL, schedM1, schedM2, fiscalYear)
 * @param {object} props.businessProfile - the LLC FROM-side identity (legal_name, ein)
 */
export default function Form1065Document({ form1065, businessProfile }) {
  const fy = form1065?.fiscalYear ?? '';
  const p = form1065?.page1 || {};
  const business = businessProfile || {};
  const schedL = form1065?.schedL || { beginning: {}, ending: {} };
  const m2 = form1065?.schedM2?.perPartner || [];

  return (
    <Document>
      {/* ── Page 1: Income & Deductions ── */}
      <Page size="LETTER" style={s.page}>
        <Text style={s.title}>Form 1065: U.S. Return of Partnership Income</Text>
        <Text style={s.subtitle}>
          {(business.legal_name || 'Nysterys Media LLC')}
          {business.ein ? `   EIN ${business.ein}` : ''}
          {'   ·   Fiscal year '}{fy}
        </Text>

        <Text style={s.section}>Income</Text>
        <LineRow line="1a"  label="Gross receipts or sales, cash basis (incl. in-kind 4200; excl. returns 4900)" amount={p.line1a} />
        <LineRow line="1b"  label="Returns and allowances"                                            amount={p.line1b} />
        <LineRow line="1c"  label="Net receipts (1a − 1b)"                                            amount={p.line1c} />
        <LineRow line="2"   label="Cost of revenue (5xxx)"                                            amount={p.line2} />
        <View style={s.total}>
          <Text style={s.cellLine}>3</Text>
          <Text style={s.cellLabel}>Gross profit (1c − 2)</Text>
          <Text style={s.cellAmt}>{F(p.line3)}</Text>
        </View>
        <Text style={s.tag}>
          Audit (per books, before the cash-basis conversion on Schedule M-1):
          non-in-kind revenue {F(p.cashRevenue)}; in-kind revenue {F(p.inKindRevenue)}.
        </Text>

        <Text style={s.section}>Deductions</Text>
        <LineRow line="9"   label="Salaries and wages (creator payroll, 511x)"                        amount={p.line9} />
        <LineRow line="20"  label="Other deductions (operating expenses, non-5xxx)"                   amount={p.line20} />
        <View style={s.rowDim}>
          <Text style={s.cellLine} />
          <Text style={s.cellLabel}>     of which: in-kind compensation passed to creators (5210x: included in line 2)</Text>
          <Text style={s.cellAmt}>{F(p.inKindComp)}</Text>
        </View>
        <View style={s.total}>
          <Text style={s.cellLine}>21</Text>
          <Text style={s.cellLabel}>Total deductions (2 + 9 + 20)</Text>
          <Text style={s.cellAmt}>{F(p.line21)}</Text>
        </View>

        <View style={[s.total, { marginTop: 18, fontSize: 12 }]}>
          <Text style={s.cellLine}>22</Text>
          <Text style={s.cellLabel}>Ordinary business income (loss)</Text>
          <Text style={[s.cellAmt, { color: P.orange }]}>{F(p.line22)}</Text>
        </View>

        <Text style={s.footer}>Page 1 of 2 · Generated from Nysterys ledger · FY {fy}</Text>
      </Page>

      {/* ── Page 2: Schedules B / K / L / M-1 / M-2 ── */}
      <Page size="LETTER" style={s.page}>
        <Text style={s.title}>Form 1065: Schedules</Text>
        <Text style={s.subtitle}>{(business.legal_name || 'Nysterys Media LLC')} · FY {fy}</Text>

        <Text style={s.section}>Schedule B: Other information</Text>
        <View style={s.row}><Text style={s.cellLabel}>Type of entity</Text><Text style={s.cellAmt}>Domestic LLC</Text></View>
        <View style={s.row}><Text style={s.cellLabel}>Accounting method</Text><Text style={s.cellAmt}>Cash basis</Text></View>
        <View style={s.row}><Text style={s.cellLabel}>Number of partners</Text><Text style={s.cellAmt}>{m2.length}</Text></View>
        <View style={s.row}><Text style={s.cellLabel}>Creator compensation</Text><Text style={s.cellAmt}>
          {form1065?.schedB?.creatorCompBasis === 'w2' ? 'W-2 wages (line 9)'
            : form1065?.schedB?.creatorCompBasis === 'mixed' ? 'W-2 wages (line 9) and 1099-NEC (line 2)'
            : '1099-NEC (line 2)'}
        </Text></View>

        <Text style={s.section}>Schedule K: Partners' distributive share items</Text>
        <LineRow line="1" label="Ordinary business income (loss)" amount={form1065?.schedK?.line1} />

        <BSSection title="Schedule L: Balance Sheets per Books"
                   beginning={[...(schedL.beginning?.assets || []), ...(schedL.beginning?.liabilities || []), ...(schedL.beginning?.equity || [])]}
                   ending={[...(schedL.ending?.assets || []), ...(schedL.ending?.liabilities || []), ...(schedL.ending?.equity || [])]} />

        <Text style={s.section}>Schedule M-1: Reconciliation of income (loss) per books vs. return</Text>
        <View style={s.row}><Text style={s.cellLabel}>Net income (loss) per books (accrual)</Text><Text style={s.cellAmt}>{FS(form1065?.schedM1?.netIncomePerBooks)}</Text></View>
        <View style={s.rowDim}><Text style={s.cellLabel}>     less: invoiced but not collected in year (11xx receivables)</Text><Text style={s.cellAmt}>{FS(form1065?.schedM1?.receivablesNotCollected)}</Text></View>
        <View style={s.rowDim}><Text style={s.cellLabel}>     add: expensed but not paid in year (21xx payables)</Text><Text style={s.cellAmt}>{FS(form1065?.schedM1?.expensesNotPaid)}</Text></View>
        <View style={s.row}><Text style={s.cellLabel}>Net income (loss) per return (cash basis)</Text><Text style={s.cellAmt}>{FS(form1065?.schedM1?.netIncomePerReturn)}</Text></View>
        <View style={s.row}><Text style={s.cellLabel}>Reconciliation difference (books − return)</Text><Text style={s.cellAmt}>{FS(form1065?.schedM1?.reconciliation)}</Text></View>

        <Text style={s.section}>Schedule M-2: Analysis of partners' capital accounts</Text>
        <View style={s.m2hdr}>
          <Text style={s.m2colName}>Partner</Text>
          <Text style={s.m2colNum}>Beginning</Text>
          <Text style={s.m2colNum}>Income share</Text>
          <Text style={s.m2colNum}>Contribs</Text>
          <Text style={s.m2colNum}>Distribs</Text>
          <Text style={s.m2colNum}>Ending</Text>
        </View>
        {m2.map((r) => (
          <View key={r.partner.id} style={s.bsRow}>
            <Text style={s.m2colName}>{r.partner.full_name} ({r.allocationPct}%)</Text>
            <Text style={s.m2colNum}>{F(r.beginning)}</Text>
            <Text style={s.m2colNum}>{F(r.share)}</Text>
            <Text style={s.m2colNum}>{F(r.contributions)}</Text>
            <Text style={s.m2colNum}>{F(r.distributions)}</Text>
            <Text style={s.m2colNum}>{F(r.ending)}</Text>
          </View>
        ))}

        <Text style={s.footer}>Page 2 of 2 · Generated from Nysterys ledger · FY {fy}</Text>
      </Page>
    </Document>
  );
}
